    oversize_fees = inputs["checked_bag_oversize_fees"]
    overweight_fees = inputs["checked_bag_overweight_fees"]
    fee_total = 0
    for i in range(len(base_fees)):
        if premises["use_higher_excess_fee"]:
            excess_fee = max(oversize_fees[i], overweight_fees[i])
        else:
            excess_fee = oversize_fees[i] + overweight_fees[i]
        fee_total = fee_total + base_fees[i] + excess_fee
    answer = int(inputs["ticket_price"] + fee_total)
    return {"answer": answer}

